@inherits Umbraco.Cms.Web.Common.UmbracoViewPage<Umbraco.Bench.Umbraco.Models.BlogPost>
@using Umbraco.Cms.Web.Common

@{
    var featuredImage = Model.Value<MediaWithCrops>("featuredImage");
}

<!DOCTYPE html>
<html>
<head>
    <title>@Model.Value("title") - Blog</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body>
    <div class="container mx-auto px-4 py-8">
        <a href="/" class="text-blue-500 hover:underline mb-4 inline-block">&larr; Back to Blog</a>

        <article class="max-w-3xl mx-auto">
            <h1 class="text-4xl font-bold mb-4">@Model.Value("title")</h1>

            @if (featuredImage != null)
            {
                <img src="@featuredImage.GetCropUrl(width: 800)" alt="Featured image" class="w-full rounded-lg mb-6" />
            }

            <div class="prose prose-lg max-w-none">
                @Html.Raw(Model.Value("content"))
            </div>

            <hr class="my-8" />
            <a href="/" class="text-blue-500 hover:underline">&larr; Back to Blog</a>
        </article>
    </div>

    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</body>
</html>

