@using Umbraco.Cms.Web.Common.PublishedModels;
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<Umbraco.Bench.Umbraco.Models.BlogFrontPage>
@{
	Layout = null;
}
<!DOCTYPE html>
<html>
<head>
	<title>@Model.Value("title")</title>
	<link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body>
	<div class="container mx-auto px-4 py-8">
		<h1 class="text-5xl font-bold mb-12 text-center">@Model.Value("title")</h1>

		<div class="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-4xl mx-auto">
			@foreach (var post in Model.Children<Umbraco.Bench.Umbraco.Models.BlogPost>())
			{
				var featured = post.Value<MediaWithCrops>("featuredImage");
				<article class="border rounded-lg overflow-hidden shadow-lg hover:shadow-xl transition-shadow">
					@if (featured != null)
					{
						<img src="@featured.GetCropUrl(width: 400, height: 250)" alt="@post.Value("title")" class="w-full h-48 object-cover" />
					}
					<div class="p-6">
						<h2 class="text-2xl font-bold mb-2">@post.Value("title")</h2>
						<p class="text-gray-600 mb-4">Discover insights about Model Context Protocol and modern development practices.</p>
						<a href="@post.Url()" class="text-blue-500 hover:underline font-semibold">Read More →</a>
					</div>
				</article>
			}
		</div>
	</div>

	<script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</body>
</html>

